"""Metadata/AST eligibility only: no imports of author generators, no signals."""
import pathlib,sys,json,hashlib,ast,datetime,time,os,platform
ROOT=pathlib.Path(__file__).resolve().parents[1];PROJECT=ROOT.parent;OUT=ROOT/'outputs';OUT.mkdir(parents=True,exist_ok=True)
SOURCE=PROJECT/'upstream'/'causal_chamber_metadata73_0c8a77ea'
def sha(b):return hashlib.sha256(b).hexdigest()
def read(p):return json.loads(pathlib.Path(p).read_text(encoding='utf-8-sig'))
def write(p,obj):
 with pathlib.Path(p).open('x',encoding='utf-8') as f:json.dump(obj,f,indent=2,allow_nan=False)
def scalar(node):
 if isinstance(node,ast.Call) and isinstance(node.func,ast.Name) and node.func.id=='int' and len(node.args)==1:return int(ast.literal_eval(node.args[0]))
 return ast.literal_eval(node)
def assignment(tree,name):
 nodes=[n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id==name for t in n.targets)];assert len(nodes)==1,name
 return scalar(nodes[0])
def dict_literal(tree,name):
 n=next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id==name for t in n.targets));assert isinstance(n,ast.Dict)
 return ast.literal_eval(n)
def code(tree):return ast.unparse(tree)
def main():
 started=time.perf_counter();sel=read(ROOT/'SOURCE_SELECTION73_V1.json');assert sel['revision']=='0c8a77ea14bd4437b1fdd79adc1aa91ac2342569' and len(sel['files'])==9
 verified=[];trees={};texts={}
 for spec in sel['files']:
  raw=(SOURCE/spec['path']).read_bytes();assert len(raw)==spec['bytes'] and sha(raw)==spec['sha256'];assert hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()==spec['git_blob_sha1'];verified.append(spec);texts[spec['path']]=raw.decode()
  if spec['path'].endswith('.py'):trees[spec['path']]=ast.parse(raw)
 assert len(trees)==5
 pressure=trees['datasets/wt_pressure_control_v1/generators/hatch.py'];assert assignment(pressure,'N')==10000
 loop=next(n for n in pressure.body if isinstance(n,ast.For));assert ast.literal_eval(loop.iter)==[0]
 assert not {'load_in','load_out'}&set(dict_literal(pressure,'exogenous_zeros'))
 pmd=texts['datasets/wt_pressure_control_v1/README.md'];assert 'PID controller' in pmd and 'hatch\\_0' in pmd
 change=trees['datasets/wt_changepoints_v1/generators/load_in.py'];assert 'load_out' in dict_literal(change,'exogenous_zeros')
 calls=[n for n in ast.walk(change) if isinstance(n,ast.Call) and ast.unparse(n.func)=='utils.set_and_measure'];assert len(calls)==1
 assert ast.literal_eval(calls[0].args[0])=={'load_in':{.01,.1,.2,.5}}
 assert next(scalar(k.value) for k in calls[0].keywords if k.arg=='n_interventions')==10
 assert 'sensor' in texts['datasets/wt_changepoints_v1/README.md']
 light=trees['datasets/lt_walks_v1/generators/smooth_polarizers.py'];assert assignment(light,'N')==10000
 sensor=dict_literal(light,'sensor_parameters');assert sensor['pol_2']==0 and sensor['osr_c']==8
 assert any(isinstance(n,ast.Call) and ast.unparse(n.func)=='np.linspace' and [ast.literal_eval(a) if not isinstance(a,ast.Name) else a.id for a in n.args]==[-90,180,'N'] for n in ast.walk(light))
 buch=trees['datasets/lt_crl_benchmark_v1/generators/buchholz_1.py'];assert assignment(buch,'N')==10000
 cit=trees['datasets/lt_crl_benchmark_v1/generators/citris_1.py'];assert assignment(cit,'N')==100000 and assignment(cit,'burn_in')==1000
 bsettings=dict_literal(buch,'exogenous_zeros');csettings=dict_literal(cit,'exogenous_zeros');assert bsettings['aperture']==csettings['aperture']=='1.8' and bsettings['iso']==csettings['iso']=='500' and bsettings['shutter_speed']==csettings['shutter_speed']=='1/200'
 assert 'prev.green' in code(cit) and 'prev.red' in code(cit) and 'flag == 5' in code(cit)
 findings=[
  dict(dataset='wt_pressure_control_v1',design='One hatch_0 protocol;10000 measurements; fixed control target and exogenous settings; fan loads generated by feedback.',available_role='Closed-loop physical control record.',joint_shift_cohort=False,reason='Inspected design supplies no sequence crossing sensor and plant-mechanism changes. Future realized fan loads are endogenous, not an externally supplied open-loop plan.',source=['datasets/wt_pressure_control_v1/README.md','datasets/wt_pressure_control_v1/generators/hatch.py']),
  dict(dataset='wt_changepoints_v1',design='Ten seeds; intake-load values0.01/0.1/0.2/0.5; ten input interventions per protocol; other settings held fixed.',available_role='Prescribed-input transient and change-detection records.',joint_shift_cohort=False,reason='The inspected changepoints are actuator-input changes. They do not document a changed plant transition law or sequential unknown sensor interface.',source=['datasets/wt_changepoints_v1/README.md','datasets/wt_changepoints_v1/generators/load_in.py']),
  dict(dataset='lt_walks_v1/smooth_polarizers',design='10000 measurements; fixed sensor settings; first polarizer sweeps-90..180; three blocks alter input distributions.',available_role='Controlled optical-transmission and input-distribution change.',joint_shift_cohort=False,reason='Can study a declared optical/interface effect, but this design does not also establish changing underlying dynamics. Treating every actuator or distribution change as a new law is invalid.',source=['datasets/lt_walks_v1/README.md','datasets/lt_walks_v1/generators/smooth_polarizers.py']),
  dict(dataset='lt_crl_benchmark_v1',design='Buchholz:10000 independent SCM samples per environment. CITRIS:100000 temporal actuator states after1000 burn-in steps; per-step interventions; both have fixed camera settings.',available_role='Physical nonlinear observations of static-SCM or controlled temporal latent factors, respectively.',joint_shift_cohort=False,reason='The two protocols must not be conflated. Intervention environments and temporal state changes are not documented sequential camera/sensor replacements plus plant-law changes. Future nonintervened actuator states must be simulated if used as latent state, not supplied as known drivers.',source=['datasets/lt_crl_benchmark_v1/README.md','datasets/lt_crl_benchmark_v1/generators/buchholz_1.py','datasets/lt_crl_benchmark_v1/generators/citris_1.py'])]
 history=[]
 for rel in ['cycle22/EXPERIMENT_PLAN.md','cycle22/baseline_registry.md','cycle69/baseline_registry.md']:
  raw=(PROJECT/rel).read_bytes();history.append(dict(path=rel,bytes=len(raw),sha256=sha(raw)))
 assert 'wt_walks_v1' in (PROJECT/'cycle22'/'EXPERIMENT_PLAN.md').read_text(encoding='utf-8')
 obj=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),status='CLOSED_METADATA_SCREEN_NO_COMPLETE_JOINT_SHIFT_COHORT_IN_FOUR_DESIGNS',source_repo=sel['repo'],source_revision=sel['revision'],source_files_verified=verified,source_bytes=sum(x['bytes'] for x in verified),generator_asts_parsed=5,author_generators_executed=0,raw_signal_or_image_files_downloaded=0,new_model_fits=0,new_model_performance_rows=0,findings=findings,historical_evidence_checked=history,history_scope='Limited direct C22/C69 evidence. No project-wide never-used certification; original C22 wind records and C69 scored records excluded from fresh-cohort claims.',decision='DO_NOT_START_JOINT_SHIFT_MODEL_COMPARISON_ON_THESE_DESIGNS_ALONE',next_action='Identify independently unused, sufficiently excited physical records; if observation shifts are constructed, declare them synthetic measurement interventions over real trajectories. Keep plant-input shifts separate from plant-law changes. Compare complete ordinary observation-adapter/state-space/replay controls before designing a new mechanism.',formal_c71_training_protocol_changed=False,accepted_final_directions=0,overall_goal='ACTIVE_UNACHIEVED',local_result_files_written=0,wall_seconds=time.perf_counter()-started)
 write(OUT/'COHORT_ELIGIBILITY73_V1.json',obj)
 md='''# C73: prospective cohort eligibility

This source/metadata audit does not run a forecasting model or establish a new research gap. Nine pinned files were verified; five generator ASTs were inspected without importing or executing the author programs. No signal or image files were downloaded. The source revision and file hashes are in outputs/COHORT_ELIGIBILITY73_V1.json.

| Design | What the actual protocol changes | Decision for joint unknown-interface/mechanism shifts |
|---|---|---|
| Wind pressure control | One fixed hatch/control-target experiment; feedback determines fan loads | Does not supply a joint-shift sequence; future loads are endogenous |
| Wind changepoints | Intake-fan command changes while other settings stay fixed | Input-transient task, not evidence of changed physical laws |
| Smooth polarizers | Optical actuator sweep and three input-distribution blocks; fixed sensor parameters | Useful declared optical/interface condition, insufficient joint dynamics change |
| CRL Buchholz / CITRIS | Independent SCM samples / temporal latent actuator process with per-step interventions; fixed camera | Keep the static and temporal experiments separate; neither alone supplies the required joint-shift sequence |

These judgments concern the proposed contract, not the datasets' general value. In particular, CITRIS genuinely contains temporal dependencies; this audit does not call the entire CRL dataset static. If its nonintervened actuators are treated as future latent state, their future truth is not a valid known-driver input. A predeclared intervention plan has a different role. Metadata does not prove an arbitrary forecasting model will fail.

Historical C22 wind recordings and C69 scored physical-system records cannot be relabeled fresh. Hashes of the directly checked old protocol/registry are retained; this limited check does not certify every other possible record as unused. The four screened designs alone do not justify starting a joint-shift model comparison. A future constructed sensor change must be explicitly identified as a synthetic observation intervention on real trajectories, while a plant input intervention stays distinct from a changed transition law.

The next work remains independent data/contract selection and complete ordinary observer, nonlinear-alignment, state-space and replay controls. No distinct new learning mechanism is validated. C71's formal budget and assessment stay unchanged. No final direction accepted; overall research goal ACTIVE/UNACHIEVED.
'''
 with (ROOT/'COHORT_DECISION73_V1.md').open('x',encoding='utf-8') as f:f.write(md)
 entries={
  'literature_review.md':'The targeted current method boundary is cycle71/NOVELTY_BOUNDARY71_V4.md. This screen adds four author-documented data contracts, not a literature completeness claim.',
  'baseline_registry.md':'No new model trained. Prospective controls remain complete frozen-dynamics observers with observation adapters, unrestricted recurrent/state-space adaptation with replay, factorized observation/dynamics contexts and capacity-matched fixed-state models. No author generator executed.',
  'experimental_results.md':'Nine source files40091 bytes passed SHA256/Git/size checks; five ASTs parsed. All four screened designs are insufficient by themselves for the declared joint-shift cohort. Zero raw signal/image downloads, zero fits and zero performance rows. Full reasoning is in COHORT_DECISION73_V1.md.',
  'negative_evidence.md':'Wind command changepoints are not evidence of changed physical laws; a single closed-loop pressure record does not supply sequential joint shifts. Fixed-camera static/temporal CRL protocols cannot be relabeled changing sensors. Preserve CITRIS temporal structure. These are contract exclusions, not model-failure or impossibility results.',
  'hypothesis_space.md':'Still untested: whether complete ordinary controls fail to preserve/reuse dynamics under independently specified sequential observation and mechanism changes. A source protocol mismatch cannot support that hypothesis. Non-identifiability must be handled with uncertainty rather than forced latent-truth scoring.',
  'research_ideas.md':'Sequential observation/dynamics reuse remains a provisional development question from C71. This metadata audit does not create a contribution. Prefer an explicit synthetic measurement-shift operator on unused real trajectories over falsely describing ordinary input changes as changed dynamics; validate across independent systems.',
  'final_research_direction.md':'No accepted final direction. Do not start a claimed joint-shift comparison on these four designs alone. Need prospective unused records, a valid information contract, a failure surviving complete ordinary controls and a distinct mechanism. Full autonomous goal remains ACTIVE/UNACHIEVED.'}
 for name,body in entries.items():
  with (ROOT/name).open('x',encoding='utf-8') as f:f.write('# '+name[:-3].replace('_',' ')+'\n\n'+body+'\n\nSee COHORT_DECISION73_V1.md and outputs/COHORT_ELIGIBILITY73_V1.json.\n')
 print(json.dumps(dict(status=obj['status'],verified_source_files=9,source_bytes=obj['source_bytes'],parsed_generator_asts=5,eligible_complete_cohorts=0,raw_signal_downloads=0,new_model_fits=0,wall_seconds=obj['wall_seconds'])),flush=True)
if __name__=='__main__':main()
